'use strict';
const DEVELOPMENT21={base:{label:'Тренировочная база',cost:[0,150000,300000,500000,800000],bonus:[.01,.02,.03,.04,.05],speed:[1,1.15,1.35,1.6,1.9]},staff:{label:'Тренерский штаб',cost:[0,125000,250000,450000,700000],form:[1,1.1,1.2,1.3,1.4],growth:[1,1.25,1.5,1.75,2]}};
function ensureDevelopment21(){if(!S)return;for(let t of S.teams){let c=clubState13(t);c.development21??={base:clamp(t.id===S.club?S.facility:c.facility,1,5),staff:clamp(Math.round(((t.id===S.club?S.coach:c.coach)-75)/5)+1,1,5),preparation:50};}
 for(let p of S.players)p.progress21??={initialForm:p.form,initialSkill:p.skill,successfulDays:0,lastOfficialDay:null,lastTitleDay:null,lastPenaltyDay:null,results:[],lastDailyDay:S.day};
 S.developmentVersion21=21;}
function development21(id=S.club){ensureDevelopment21();return clubState13(S.teams[id]).development21;}
const initBefore21=init13;init13=function(){initBefore21();ensureDevelopment21();};
function formRecord21(p,win,event=null){ensureDevelopment21();let g=p.progress21;g.results=g.results.filter(r=>S.day-r.day<=90);g.results.push({day:S.day,win:!!win,event});g.results=g.results.slice(-180);g.lastOfficialDay=S.day;
 if(!win&&g.lastPenaltyDay!==S.day){p.form=clamp(p.form-.35,35,95);g.lastPenaltyDay=S.day;}
}
function formWindow21(p){let g=p.progress21,results=(g?.results||[]).filter(r=>S.day-r.day<=30),wins=results.filter(r=>r.win).length;return {games:results.length,wins,rate:results.length?wins/results.length:0};}
function growthQuality21(p){let r=formWindow21(p);return clamp((r.rate-.35)/.4,0,1)*Math.min(1,r.games/6);}
// Form has a calendar-time ceiling: no number of same-day wins can create a peak.
playerGrowth13=function(p,mode,facility,focus){if(p.retired)return;ensureDevelopment21();let g=p.progress21,d=p.team==null?{staff:1,base:1,preparation:0}:development21(p.team),staff=DEVELOPMENT21.staff,rest=mode==='rest',intense=mode==='intensive',q=growthQuality21(p),gap=g.lastOfficialDay==null?Infinity:S.day-g.lastOfficialDay,headroom=Math.max(0,p.potential-p.skill),energy=clamp((100-p.fatigue)/80,0,1);
 if(g.lastDailyDay!==S.day){
  if(p.active&&q>=.6&&gap<=21)g.successfulDays=Math.min(90,g.successfulDays+1);else g.successfulDays=Math.max(0,g.successfulDays-(gap>30?1:.3));
  let title=g.lastTitleDay!=null&&S.day-g.lastTitleDay<=90,ceiling=Math.min(95,Math.max(g.initialForm,75+20*Math.min(1,g.successfulDays/60))),target=70+25*q*(title?1:.9);
  if(p.active&&gap<=21&&q>.3&&target>p.form)p.form=Math.min(ceiling,target,p.form+.28*staff.form[d.staff-1]*(rest?.7:1));
  else if(gap>21)p.form=Math.max(p.active?55:50,p.form-(gap>45?.22:.08));
  else if(q<.35&&p.form>65)p.form=Math.max(65,p.form-.1);
  let amount=rest?0:.006*staff.growth[d.staff-1]*clamp(headroom/8,.15,1)*energy*q*(intense?1.1:1)*(p.active?1:.2);
  if(headroom>0)p.skill=Math.min(p.potential,p.skill+amount);
  if(!rest&&p.attributes13&&Number.isFinite(p.attributes13[focus]))p.attributes13[focus]=clamp(p.attributes13[focus]+amount*2,40,99);
  p.fatigue=clamp(p.fatigue+(rest?-12:intense?4:-1));p.morale=clamp(p.morale+(rest?.5:intense?-.3:.05)+(p.active?0:-.2),20,98);
  if(!rest&&focus==='versatility'){let h=playerPool4(p)[(S.day+p.id)%playerPool4(p).length]?.hero;if(h)p.heroPractice13[h]=Math.min(20,(p.heroPractice13[h]||0)+.12*DEVELOPMENT21.base.speed[d.base-1]);}
  p.form=clamp(p.form,35,95);g.lastDailyDay=S.day;
 }
};
const tickBefore21=tick;tick=function(){ensureDevelopment21();tickBefore21();for(let t of S.teams){let c=clubState13(t),d=c.development21,own=t.id===S.club;
 // Keep existing AI investments and player-owned levels in the same economy.
 if(!own){d.base=Math.max(d.base,clamp(c.facility,1,5));d.staff=Math.max(d.staff,clamp(Math.round((c.coach-75)/5)+1,1,5));}
 let mode=own?S.training:c.training;d.preparation=clamp(d.preparation+(mode==='rest'?.12:mode==='intensive'?.8:.5)*DEVELOPMENT21.base.speed[d.base-1]);
 }};
resultImpact13=function(m){if(m.careerResult13)return;m.careerResult13=true;ensureDevelopment21();let ids=m.sides.map(s=>s.team),winner=m.finishedSide,official=m.scope13!=='scrim';
 for(let side of [0,1]){let t=S.teams[ids[side]],c=clubState13(t),victory=side===winner;for(let p of roster(t)){
  if(official)formRecord21(p,victory,S.active?.event??null);
  p.morale=clamp(p.morale+(victory?1.5:-1.5),20,98);let hero=m.sides[side].heroes.find(q=>q.role===p.role)?.hero;if(hero)p.heroPractice13[hero]=Math.min(20,(p.heroPractice13[hero]||0)+.35);
 }
 if(!official)continue;c.development21.preparation=clamp(c.development21.preparation-2);c.maps++;c.wins+=Number(victory);c.lastResults.push(victory);c.lastResults=c.lastResults.slice(-10);
 }
 if(official){let a=clubState13(S.teams[ids[0]]),b=clubState13(S.teams[ids[1]]),expected=1/(1+10**((b.elo-a.elo)/400)),change=18*((winner===0?1:0)-expected);a.elo+=change;b.elo-=change;}
};
function tournamentDevelopment21(e){if(!e?.done||e.developmentApplied21)return;ensureDevelopment21();e.developmentApplied21=true;let placements=e.placements6||{};
 for(let [id,place] of Object.entries(placements)){let team=S.teams[+id];if(!team)continue;let penalty=place>8?.07:place>4?.04:0;
  for(let p of e.competitors21?.[id]?.map(pid=>S.players[pid]).filter(Boolean)||roster(team)){let g=p.progress21;if(penalty){p.form=clamp(p.form*(1-penalty),35,95);g.successfulDays=Math.max(0,g.successfulDays-(place>8?7:4));g.earlyExit21={day:S.day,place,percent:penalty*100};}if(place===1)g.lastTitleDay=S.day;}
  if(+id===S.club&&penalty)log('Ранний вылет из '+e.name+': форма основы −'+Math.round(penalty*100)+'% (место '+place+').');
 }
}
const eventFinishBefore21=finishEvent6;finishEvent6=function(a){let e=S.events.find(e=>e.id===a.event);if(e&&!e.done)e.competitors21=Object.fromEntries(a.entrants.map(id=>[id,roster(S.teams[id]).map(p=>p.id)]));eventFinishBefore21(a);tournamentDevelopment21(e);if(e?.done)render();};
const skipFinishBefore21=finalizeSkipped12;finalizeSkipped12=function(a){let e=S.events.find(e=>e.id===a.event);skipFinishBefore21(a);if(e){let copy={...e,placements6:Object.fromEntries(Object.entries(e.placements6||{}).filter(([id])=>+id!==S.club))};tournamentDevelopment21(copy);e.developmentApplied21=true;}};
const mapInitBefore21=initMap13;initMap13=function(m){mapInitBefore21(m);if(m.preparation21)return;ensureDevelopment21();m.preparation21=m.sides.map(s=>{let d=development21(s.team);return m.clock===0?DEVELOPMENT21.base.bonus[d.base-1]*d.preparation/100:0;});};
const powerBefore21=unitPower5;unitPower5=function(m,p){let side=m.sides.findIndex(s=>s.heroes.includes(p));return powerBefore21(m,p)*(1+(m.preparation21?.[side]||0));};
function upgradeDevelopment21(kind){if(!['base','staff'].includes(kind)||locked())return false;let d=development21(),level=d[kind];if(level>=5)return false;let cost=DEVELOPMENT21[kind].cost[level];if(S.budget<cost){toast('Недостаточно средств');return false;}money(-cost,'Развитие: '+DEVELOPMENT21[kind].label+' · уровень '+(level+1));d[kind]++;
 if(kind==='base')S.facility=d.base;else S.coach=75+(d.staff-1)*5;
 log(DEVELOPMENT21[kind].label+': уровень '+d[kind]+'/5.');render();return true;}
upgradeBase=function(){return upgradeDevelopment21('base');};upgradeCoach=function(){return upgradeDevelopment21('staff');};
function developmentView21(){let d=development21();return head('ИНФРАСТРУКТУРА КЛУБА','Развитие','База готовит команду к турнирам. Штаб развивает игроков.')+`<div class="development-grid21">${['base','staff'].map(kind=>{let cfg=DEVELOPMENT21[kind],level=d[kind];return `<section class="panel development-card21"><h2>${cfg.label}</h2><div class="building-icon21">${kind==='base'?icon21('base'):icon21('team')}</div><div class="level-pips21">${[1,2,3,4,5].map(n=>`<span class="${n<=level?'filled':''}">${n}</span>`).join('')}</div><h3>Уровень ${level} / 5</h3>${kind==='base'?`<p>Бонус к эффективности команды: до <b>+${Math.round(cfg.bonus[level-1]*100)}%</b> при полной подготовке.</p><p>Скорость подготовки: <b>×${cfg.speed[level-1]}</b>.</p>${bar('Подготовка к турниру',d.preparation)}<p class="sub">Текущий бонус +${(cfg.bonus[level-1]*d.preparation).toFixed(2)}%. После официальной карты подготовка −2 п.п. Бонус фиксируется при старте карты.</p>`:`<p>Скорость набора формы: <b>×${cfg.form[level-1]}</b>.</p><p>Реализация потенциала: <b>×${cfg.growth[level-1]}</b>.</p><p class="sub">Ускоряет развитие при успешных выступлениях. Пик формы всё равно требует не менее 60 успешных календарных дней.</p>`}${level<5?btn('Улучшить · '+cash(cfg.cost[level]),`upgradeDevelopment21('${kind}')`,true,locked()||S.budget<cfg.cost[level]):'<span class="tag">Максимальный уровень</span>'}${locked()?'<p class="sub">Улучшения доступны после завершения турнира или КВ.</p>':''}<details><summary>Все уровни</summary><table><thead><tr><th>Ур.</th><th>Эффект</th><th>Цена</th></tr></thead><tbody>${[1,2,3,4,5].map(n=>`<tr><td>${n}</td><td>${kind==='base'?'до +'+Math.round(cfg.bonus[n-1]*100)+'% · ×'+cfg.speed[n-1]:'форма ×'+cfg.form[n-1]+' · рост ×'+cfg.growth[n-1]}</td><td>${n===1?'Стартовый':cash(cfg.cost[n-1])}</td></tr>`).join('')}</tbody></table></details></section>`;}).join('')}</div><section class="panel progress-rules21"><h2>Форма и потенциал</h2><p><b>Форма</b> растёт от частых побед в официальных матчах и титулов. Пик — 95/100, ориентир 60–90 дней успешных выступлений. Большое число карт за один день не ускоряет календарный предел. После 21 дня без официальной практики начинается постепенное снижение.</p><p><b>Ранний вылет:</b> места 5–8 — потеря 4% текущей формы, 9-е и ниже — 7%. Для топ‑4 штрафа нет. КВ дают практику героев, но не заменяют турнирные победы.</p><p><b>Потенциал</b> — потолок рейтинга. Рейтинг растёт месяцами: победы, энергия и работа штаба ускоряют рост; частые поражения и отдых его замедляют. Краткосрочные поражения снижают форму, а не стирают приобретённый навык.</p></section><section class="panel"><h2>Развитие игроков основы</h2><div class="table-wrap"><table><thead><tr><th>Игрок</th><th>Форма</th><th>Дней успеха</th><th>OVR → потенциал</th><th>Рост OVR</th></tr></thead><tbody>${roster().map(p=>`<tr><td>${playerLink20(p)}</td><td>${p.form.toFixed(1)} / 95</td><td>${Math.floor(p.progress21.successfulDays)} / 60</td><td>${p.skill.toFixed(2)} → ${p.potential}</td><td>+${Math.max(0,p.skill-p.progress21.initialSkill).toFixed(2)}</td></tr>`).join('')}</tbody></table></div></section>`;}
const tacticsBefore21=tactics;tactics=function(){return tacticsBefore21().replaceAll('форма стремится к 75.','набор формы зависит от турнирных результатов.').replaceAll('форма стремится к 82.','потенциал растёт при успешных выступлениях.').replaceAll('форма постепенно снижается к 68.','практика и результаты определяют динамику формы.')+`<section class="panel"><h2>Инфраструктура</h2><p>Подготовка: ${Math.round(development21().preparation)}%. База ${development21().base}/5 · штаб ${development21().staff}/5.</p>${btn('Развитие клуба →',"go('development')",true)}</section>`;};
const playerViewBefore21=playerView20;playerView20=function(){let p=S.players[selectedPlayer20],html=playerViewBefore21();if(!p||p.retired)return html;let g=p.progress21;return html+`<section class="panel player-growth21"><h2>Реализация потенциала</h2><div class="growth-values21"><strong>${p.skill.toFixed(2)} <small>OVR</small> → ${p.potential} <small>потенциал</small></strong><span>+${Math.max(0,p.skill-(g?.initialSkill??p.skill)).toFixed(2)} с начала v2.1</span></div><p>Успешных календарных дней: ${Math.floor(g?.successfulDays||0)} / 60. Официальных карт за 30 дней: ${formWindow21(p).games}.</p></section>`;};
const validateBefore21=validSave;validSave=function(x){if(!validateBefore21(x))return false;return x.teams.every(t=>!t.career13?.development21||['base','staff'].every(k=>Number.isInteger(t.career13.development21[k])&&t.career13.development21[k]>=1&&t.career13.development21[k]<=5)&&Number.isFinite(t.career13.development21.preparation)&&t.career13.development21.preparation>=0&&t.career13.development21.preparation<=100)&&x.players.every(p=>!p.progress21||['initialForm','initialSkill','successfulDays','lastDailyDay'].every(k=>Number.isFinite(p.progress21[k]))&&Array.isArray(p.progress21.results)&&p.progress21.results.length<=180&&p.progress21.results.every(r=>Number.isInteger(r.day)&&r.day>=0&&typeof r.win==='boolean'));};
